function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go($url='index.php'){header('Location: '.$url);exit;}
function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}
function check_csrf(){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Invalid session token. Please go back and retry.');}}
function user(){return $_SESSION['user']??null;}
function admin(){return user() && user()['role']==='admin';}
function notice($m){$_SESSION['flash']=$m;}
function flash(){if(!empty($_SESSION['flash'])){$m=$_SESSION['flash'];unset($_SESSION['flash']);echo '<div class="notice">'.e($m).'</div>';}}
$action=$_POST['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 check_csrf();
 if($action==='register'){
  $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';
  if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){notice('Enter a name, valid email and password of at least 8 characters.');go('index.php?page=register');}
  try{$st=$pdo->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'student'];notice('Welcome to CodeEarn! Your account is ready.');go();}
  catch(PDOException $x){notice('That email is already registered.');go('index.php?page=register');}
 }
 if($action==='login'){
  $st=$pdo->prepare('SELECT * FROM users WHERE email=?');$st->execute([strtolower(trim($_POST['email']??''))]);$u=$st->fetch();
  if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];notice('You are signed in.');go();}
  notice('Incorrect email or password.');go('index.php?page=login');
 }
 if($action==='logout'){$_SESSION=[];session_destroy();go();}
 if($action==='enroll'||$action==='payment'||$action==='buy'){
  if(!user()){notice('Please sign in first.');go('index.php?page=login');}
  $id=(int)($_POST['id']??0);
  if($action==='enroll'){$st=$pdo->prepare('SELECT * FROM courses WHERE id=?');$st->execute([$id]);$c=$st->fetch();if($c){$s=$pdo->prepare('INSERT OR IGNORE INTO enrollments(user_id,course_id,status) VALUES(?,?,?)');$s->execute([user()['id'],$id,$c['price']===0?'approved':'pending']);notice($c['price']===0?'You are enrolled!':'Enrollment request created. Complete manual payment to get access.');}go('index.php?page=dashboard');}
  if($action==='payment'){$ref=trim($_POST['reference']??'');if($ref===''){notice('Enter your UPI transaction reference.');go('index.php?page=course&id='.$id);}$s=$pdo->prepare('INSERT INTO payments(user_id,course_id,reference) VALUES(?,?,?)');$s->execute([user()['id'],$id,$ref]);notice('Payment reference submitted. Admin will verify it manually.');go('index.php?page=dashboard');}
  $s=$pdo->prepare('INSERT INTO orders(user_id,product_id) VALUES(?,?)');$s->execute([user()['id'],$id]);notice('Product order placed. Admin will contact you after manual verification.');go('index.php?page=dashboard');
 }
 if($action==='approve_enrollment'&&admin()){$pdo->prepare("UPDATE enrollments SET status='approved' WHERE id=?")->execute([(int)$_POST['id']]);notice('Course access approved.');go('index.php?page=admin');}
 if($action==='approve_payment'&&admin()){$id=(int)$_POST['id'];$st=$pdo->prepare('SELECT user_id,course_id FROM payments WHERE id=?');$st->execute([$id]);$p=$st->fetch();if($p){$pdo->prepare("UPDATE payments SET status='verified' WHERE id=?")->execute([$id]);$pdo->prepare("INSERT OR IGNORE INTO enrollments(user_id,course_id,status) VALUES(?,?,'approved')")->execute([$p['user_id'],$p['course_id']]);$pdo->prepare("UPDATE enrollments SET status='approved' WHERE user_id=? AND course_id=?")->execute([$p['user_id'],$p['course_id']]);}notice('Payment verified and course access granted.');go('index.php?page=admin');}
 if($action==='approve_order'&&admin()){$pdo->prepare("UPDATE orders SET status='approved' WHERE id=?")->execute([(int)$_POST['id']]);notice('Product order marked as approved.');go('index.php?page=admin');}
}
